                    int x = i + dir[0];
                    int y = j + dir[1];

                    if (x >= 0 && x < m && y >= 0 && y < n && mat.get(x).get(y) == 1) {
                        live++;
                    }
                }

                //  Apply rules
                if (mat.get(i).get(j) == 1 && (live < 2 || live > 3))
                    row.add(0);
                else if (mat.get(i).get(j) == 0 && live == 3)
                    row.add(1);
                else
                    row.add(mat.get(i).get(j));
            }
            nextGen.add(row);
